1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13	)
14	
15	// Check statuses recorded per rule in a report.
16	const (
17		StatusUnchecked   = "未检查"
18		StatusPass        = "通过"
19		StatusDefect      = "发现缺陷"
20		StatusToolMissing = "工具缺失"
21		StatusTimeout     = "超时"
22	)
23	
24	// ReportArtifact identifies the audited artifact by name and content hash.
25	type ReportArtifact struct {
26		Name string `json:"name"`
27		Hash string `json:"hash"`
28	}
29	
30	// ReportRule is one rule together with the invariant check result. The note
31	// carries the original checker description: counterexample evidence for a
32	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
33	// or an optional remark for a passing check. It is empty for reports built
34	// only from invariant booleans.
35	type ReportRule struct {
36		ID          string `json:"id"`
37		Kind        string `json:"kind"`
38		Severity    string `json:"severity"`
39		Invariant   string `json:"invariant"`
40		RequiresABI bool   `json:"requiresABI"`
41		Version     string `json:"version"`
42		Status      string `json:"status"`
43		Note        string `json:"note,omitempty"`
44	}
45	
46	// ReportFinding binds a defect to its artifact, rule, version and evidence.
47	type ReportFinding struct {
48		ArtifactHash string `json:"artifactHash"`
49		RuleID       string `json:"ruleId"`
50		Version      string `json:"version"`
51		Severity     string `json:"severity"`
52		Invariant    string `json:"invariant"`
53		Evidence     string `json:"evidence"`
54	}
55	
56	// Report is the persisted audit result.
57	type Report struct {
58		ReportID string          `json:"reportId"`
59		Artifact ReportArtifact  `json:"artifact"`
60		Rules    []ReportRule    `json:"rules"`
61		Findings []ReportFinding `json:"findings"`
62	}
63	
64	// wireArtifact is the JSON shape of an artifact in an audit submission.
65	type wireArtifact struct {
66		Name     string `json:"name"`
67		ABI      string `json:"abi"`
68		Bytecode string `json:"bytecode"`
69		Source   string `json:"source"`
70	}
71	
72	// wireRule is the JSON shape of a rule in an audit submission.
73	type wireRule struct {
74		ID          string `json:"id"`
75		Kind        string `json:"kind"`
76		Severity    string `json:"severity"`
77		Invariant   string `json:"invariant"`
78		RequiresABI bool   `json:"requiresABI"`
79		Version     string `json:"version"`
80	}
81	
82	// CheckRecord is one imported per-rule check result: the artifact hash and
83	// rule version it was produced against, the conclusion status, and the
84	// original checker note (counterexample, tool or deadline remark).
85	type CheckRecord struct {
86		ArtifactHash string
87		RuleID       string
88		Version      string
89		Status       string
90		Note         string
91	}
92	
93	// wireCheck is the JSON shape of one entry in the checks array.
94	type wireCheck struct {
95		ArtifactHash string `json:"artifactHash"`
96		RuleID       string `json:"ruleId"`
97		Version      string `json:"version"`
98		Status       string `json:"status"`
99		Note         string `json:"note"`
100	}
101	
102	// wireInput is the JSON object accepted by the audit command.
103	type wireInput struct {
104		Artifact   wireArtifact               `json:"artifact"`
105		Rules      []wireRule                 `json:"rules"`
106		Invariants map[string]json.RawMessage `json:"invariants"`
107		Checks     []wireCheck                `json:"checks"`
108	}
109	
110	// submissionShape is the fixed-field shape of an audit submission: the agreed
111	// spellings at the top level and inside the artifact, every rule and every
112	// check record. The invariants object is a fixed top-level member but has no
113	// nested shape, so it passes through untouched: invariant names are
114	// user-defined rather than fixed fields, and "Inv" and "inv" stay two
115	// independent invariants and a padded name is not trimmed.
116	var submissionShape = fixedShape{
117		keys: []string{"artifact", "rules", "invariants", "checks"},
118		objects: map[string]fixedShape{
119			"artifact": {keys: []string{"name", "abi", "bytecode", "source"}},
120		},
121		arrays: map[string]fixedShape{
122			"rules":  {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version"}},
123			"checks": {keys: []string{"artifactHash", "ruleId", "version", "status", "note"}},
124		},
125	}
126	
127	// strictSubmissionJSON rewrites submission bytes to the fixed submission
128	// fields under their agreed spelling; see fixedShape for the recognition
129	// convention shared with the archive read side.
130	func strictSubmissionJSON(data []byte) ([]byte, error) {
131		return strictFixedJSON(data, submissionShape)
132	}
133	
134	// validateFormalCheckStatuses checks the formal "status" member of every
135	// strict check record. The strict rewrite dropped extension members, so the
136	// status seen here is the agreed-spelling one alone: a missing formal status,
137	// a non-string one, or an unsupported value rejects the whole submission
138	// even when an adjacent "StAtus" extension member carried a legal-looking
139	// value. The error names the rule the record is for so the offending entry is
140	// identifiable.
141	func validateFormalCheckStatuses(strict []byte) error {
142		var top struct {
143			Checks []map[string]json.RawMessage `json:"checks"`
144		}
145		if err := json.Unmarshal(strict, &top); err != nil {
146			return errInvalid("invalid JSON: " + err.Error())
147		}
148		for _, rec := range top.Checks {
149			where := "check record"
150			if raw, ok := rec["ruleId"]; ok {
151				var ruleID string
152				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
153					where = "check for rule " + ruleID
154				}
155			}
156			raw, ok := rec["status"]
157			if !ok {
158				return errInvalid(where + ": status is required")
159			}
160			var status string
161			if err := json.Unmarshal(raw, &status); err != nil {
162				return errInvalid(where + ": status must be a string")
163			}
164			if !validCheckStatus(status) {
165				return errInvalid(where + ": unknown status " + status)
166			}
167		}
168		return nil
169	}
170	
171	// ParseAuditInput decodes an audit submission JSON object into domain values.
172	// Invariant values must be JSON booleans; any other type is an error. Any JSON
173	// object in the submission that repeats a member name rejects the whole
174	// submission: the decoder keeps only the last value silently, so a repeated
175	// invariant key would choose a conclusion by member order instead of giving
176	// one trustworthy result. Only the fixed fields under their agreed spelling
177	// participate: case variants and whitespace-padded names are extension data
178	// and are ignored, so they can neither override a formal value nor supply one
179	// when the formal member is missing or unsupported. Invariant names are not
180	// fixed fields — they are user-defined, compared case sensitively and never
181	// trimmed.
182	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
183		if dup := findDuplicateJSONMember(data); dup != nil {
184			return Artifact{}, nil, nil, nil, errInvalid(duplicateMemberMessage(data, dup))
185		}
186		strict, err := strictSubmissionJSON(data)
187		if err != nil {
188			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
189		}
190		if err := validateFormalCheckStatuses(strict); err != nil {
191			return Artifact{}, nil, nil, nil, err
192		}
193		var in wireInput
194		if err := json.Unmarshal(strict, &in); err != nil {
195			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
196		}
197		invariants := make(map[string]bool, len(in.Invariants))
198		for key, raw := range in.Invariants {
199			// Only JSON true/false is a conclusion. Unmarshalling directly into a
200			// bool would turn null into the zero value false, which would falsely
201			// record a defect; require the token to be a boolean instead.
202			var token any
203			if err := json.Unmarshal(raw, &token); err != nil {
204				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
205			}
206			holds, ok := token.(bool)
207			if !ok {
208				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
209			}
210			invariants[key] = holds
211		}
212		artifact := Artifact{
213			Name:     in.Artifact.Name,
214			ABI:      in.Artifact.ABI,
215			Bytecode: in.Artifact.Bytecode,
216			Source:   in.Artifact.Source,
217		}
218		rules := make([]Rule, 0, len(in.Rules))
219		for _, wr := range in.Rules {
220			rules = append(rules, Rule{
221				ID:          wr.ID,
222				Kind:        wr.Kind,
223				Severity:    wr.Severity,
224				Invariant:   wr.Invariant,
225				RequiresABI: wr.RequiresABI,
226				Version:     wr.Version,
227			})
228		}
229		checks := make([]CheckRecord, 0, len(in.Checks))
230		for _, wc := range in.Checks {
231			checks = append(checks, CheckRecord{
232				ArtifactHash: wc.ArtifactHash,
233				RuleID:       wc.RuleID,
234				Version:      wc.Version,
235				Status:       wc.Status,
236				Note:         wc.Note,
237			})
238		}
239		return artifact, rules, invariants, checks, nil
240	}
241	
242	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
243	// bytecode and source strings contribute; field boundaries are explicit
244	// (length-prefixed) so that different splits never collide. The source is
245	// hashed as a field value, never read from disk, and the name does not
246	// participate.
247	func ArtifactHash(a Artifact) string {
248		h := sha256.New()
249		h.Write([]byte("contractsentinel-artifact-v1\n"))
250		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
251			fmt.Fprintf(h, "%d\n", len(field))
252			h.Write([]byte(field))
253		}
254		sum := h.Sum(nil)
255		return hex.EncodeToString(sum)
256	}
257	
258	// validCheckStatus reports whether status is one of the four recorded check
259	// conclusions.
260	func validCheckStatus(status string) bool {
261		switch status {
262		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
263			return true
264		}
265		return false
266	}
267	
268	// BuildReport evaluates rules against the artifact and invariant values and
269	// imported check records and produces the report to persist. Insufficient
270	// inputs (missing ABI for a rule that requires it, missing bytecode for a
271	// symbolic rule) fail the whole submission and are never recorded as defects.
272	// Imported checks are validated as a whole: unknown rules, duplicate records,
273	// unknown statuses, missing notes, hash or version mismatches, and a rule
274	// receiving both a check record and an invariant boolean all reject the
275	// submission without producing a report.
276	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
277		if artifact.Name == "" {
278			return Report{}, errInvalid("artifact name is required")
279		}
280		hash := ArtifactHash(artifact)
281		seen := make(map[string]bool, len(rules))
282		ruleByID := make(map[string]Rule, len(rules))
283		for _, rule := range rules {
284			if rule.ID == "" {
285				return Report{}, errInvalid("rule id is required")
286			}
287			if rule.Version == "" {
288				return Report{}, errInvalid("rule " + rule.ID + " version is required")
289			}
290			if seen[rule.ID] {
291				return Report{}, errInvalid("duplicate rule id " + rule.ID)
292			}
293			seen[rule.ID] = true
294			ruleByID[rule.ID] = rule
295			if rule.RequiresABI && artifact.ABI == "" {
296				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
297			}
298			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
299				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
300			}
301		}
302		checkByRule := make(map[string]CheckRecord, len(checks))
303		for _, check := range checks {
304			if check.RuleID == "" {
305				return Report{}, errInvalid("check rule id is required")
306			}
307			rule, ok := ruleByID[check.RuleID]
308			if !ok {
309				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
310			}
311			if _, dup := checkByRule[check.RuleID]; dup {
312				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
313			}
314			if check.ArtifactHash != hash {
315				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
316			}
317			if check.Version != rule.Version {
318				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
319			}
320			if !validCheckStatus(check.Status) {
321				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
322			}
323			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
324				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
325			}
326			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
327				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
328			}
329			checkByRule[check.RuleID] = check
330		}
331		report := Report{
332			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
333			Rules:    []ReportRule{},
334			Findings: []ReportFinding{},
335		}
336		for _, rule := range rules {
337			status := StatusUnchecked
338			note := ""
339			if check, ok := checkByRule[rule.ID]; ok {
340				status = check.Status
341				note = check.Note
342			} else if holds, checked := invariants[rule.Invariant]; checked {
343				if holds {
344					status = StatusPass
345				} else {
346					status = StatusDefect
347				}
348			}
349			report.Rules = append(report.Rules, ReportRule{
350				ID:          rule.ID,
351				Kind:        rule.Kind,
352				Severity:    rule.Severity,
353				Invariant:   rule.Invariant,
354				RequiresABI: rule.RequiresABI,
355				Version:     rule.Version,
356				Status:      status,
357				Note:        note,
358			})
359			if status == StatusDefect {
360				evidence := note
361				if evidence == "" {
362					evidence = "invariant " + rule.Invariant + " does not hold"
363				}
364				report.Findings = append(report.Findings, ReportFinding{
365					ArtifactHash: hash,
366					RuleID:       rule.ID,
367					Version:      rule.Version,
368					Severity:     rule.Severity,
369					Invariant:    rule.Invariant,
370					Evidence:     evidence,
371				})
372			}
373		}
374		report.ReportID = ReportID(report)
375		return report, nil
376	}
377	
378	// canonicalRule is the order-independent view of a rule used for the id. The
379	// note is omitted when empty so reports built only from invariant booleans
380	// keep their original ids.
381	type canonicalRule struct {
382		ID          string `json:"id"`
383		Kind        string `json:"kind"`
384		Severity    string `json:"severity"`
385		Invariant   string `json:"invariant"`
386		RequiresABI bool   `json:"requiresABI"`
387		Version     string `json:"version"`
388		Status      string `json:"status"`
389		Note        string `json:"note,omitempty"`
390	}
391	
392	// canonicalFinding is the order-independent view of a finding used for the id.
393	type canonicalFinding struct {
394		ArtifactHash string `json:"artifactHash"`
395		RuleID       string `json:"ruleId"`
396		Version      string `json:"version"`
397		Severity     string `json:"severity"`
398		Invariant    string `json:"invariant"`
399		Evidence     string `json:"evidence"`
400	}
401	
402	// canonicalReport is the deterministic content a report id is computed from.
403	type canonicalReport struct {
404		ArtifactHash string             `json:"artifactHash"`
405		Name         string             `json:"name"`
406		Rules        []canonicalRule    `json:"rules"`
407		Findings     []canonicalFinding `json:"findings"`
408	}
409	
410	// canonicalize renders a report into its order-independent form.
411	func canonicalize(report Report) canonicalReport {
412		cr := canonicalReport{
413			ArtifactHash: report.Artifact.Hash,
414			Name:         report.Artifact.Name,
415		}
416		for _, rule := range report.Rules {
417			cr.Rules = append(cr.Rules, canonicalRule{
418				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
419				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
420				Version: rule.Version, Status: rule.Status, Note: rule.Note,
421			})
422		}
423		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
424		for _, finding := range report.Findings {
425			cr.Findings = append(cr.Findings, canonicalFinding{
426				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
427				Version: finding.Version, Severity: finding.Severity,
428				Invariant: finding.Invariant, Evidence: finding.Evidence,
429			})
430		}
431		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
432		return cr
433	}
434	
435	// ReportID returns the content-addressed identifier of a report. The id binds
436	// the artifact hash, name, complete rule definitions, the invariant value
437	// used by each rule (unchecked and explicit pass are distinct), and the
438	// findings. Rule order, invariant key order and unrelated invariant keys do
439	// not influence it.
440	func ReportID(r Report) string {
441		data, err := json.Marshal(canonicalize(r))
442		if err != nil {
443			panic(err) // canonical values are all strings and bools
444		}
445		sum := sha256.Sum256(data)
446		return hex.EncodeToString(sum[:])
447	}
448	
449	// validateReport checks every archive legality condition against r. It is the
450	// single definition of a legal report: the id and artifact hash are 64
451	// lowercase hex characters, the id matches the content, the artifact name is
452	// present, rule ids are present and unique with non-empty versions, statuses
453	// use the five recorded values, tool-missing and timeout notes are
454	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
455	// artifact hash, version, severity, invariant and evidence match the rule.
456	// The same conditions apply to submissions and to stored archives: a
457	// recomputed id never makes an invalid report legal. fail is errInvalid for
458	// submissions and errCorrupt for stored archives.
459	func validateReport(r Report, fail func(string) error) error {
460		if !validReportID(r.ReportID) {
461			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
462		}
463		if r.Artifact.Name == "" {
464			return fail("report " + r.ReportID + " artifact name is required")
465		}
466		if !validReportID(r.Artifact.Hash) {
467			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
468		}
469		if ReportID(r) != r.ReportID {
470			return fail("report content does not match id " + r.ReportID)
471		}
472		seenRule := make(map[string]bool, len(r.Rules))
473		defectByID := make(map[string]ReportRule)
474		for _, rule := range r.Rules {
475			if rule.ID == "" {
476				return fail("report " + r.ReportID + " has a rule with an empty id")
477			}
478			if seenRule[rule.ID] {
479				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
480			}
481			seenRule[rule.ID] = true
482			if rule.Version == "" {
483				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
484			}
485			switch rule.Status {
486			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
487			default:
488				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
489			}
490			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
491				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
492			}
493			if rule.Status == StatusDefect {
494				defectByID[rule.ID] = rule
495			}
496		}
497		seenFinding := make(map[string]bool, len(r.Findings))
498		for _, f := range r.Findings {
499			if f.RuleID == "" {
500				return fail("report " + r.ReportID + " has a finding with an empty rule id")
501			}
502			rule, ok := defectByID[f.RuleID]
503			if !ok {
504				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
505			}
506			if seenFinding[f.RuleID] {
507				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
508			}
509			seenFinding[f.RuleID] = true
510			if f.ArtifactHash != r.Artifact.Hash {
511				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
512			}
513			if f.Version != rule.Version {
514				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
515			}
516			if f.Severity != rule.Severity {
517				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
518			}
519			if f.Invariant != rule.Invariant {
520				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
521			}
522			wantEvidence := rule.Note
523			if wantEvidence == "" {
524				wantEvidence = "invariant " + rule.Invariant + " does not hold"
525			}
526			if f.Evidence != wantEvidence {
527				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
528			}
529		}
530		for id := range defectByID {
531			if !seenFinding[id] {
532				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
533			}
534		}
535		return nil
536	}
537	
538	// validStoredReport validates archive contents.
539	func validStoredReport(r Report) error {
540		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
541	}
542	
543	// validSubmittedReport validates a submission before any store operation.
544	func validSubmittedReport(r Report) error {
545		return validateReport(r, func(msg string) error { return errInvalid(msg) })
546	}
547	
548	// duplicateArchiveError classifies an archive that repeats a JSON member as
549	// corrupt and names the requested report id, the decoded member name and the
550	// object carrying it (with array position and rule id when applicable).
551	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
552		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
553	}
554	
555	// reportShape is the fixed-field shape of a stored report archive: the agreed
556	// spellings at the top level and inside the artifact, every rule and every
557	// finding. The trusted content of a report is carried by these fixed fields
558	// alone; case variants, whitespace-padded names and unknown members are
559	// extension data and never reach the decoder.
560	var reportShape = fixedShape{
561		keys: []string{"reportId", "artifact", "rules", "findings"},
562		objects: map[string]fixedShape{
563			"artifact": {keys: []string{"name", "hash"}},
564		},
565		arrays: map[string]fixedShape{
566			"rules":    {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version", "status", "note"}},
567			"findings": {keys: []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}},
568		},
569	}
570	
571	// strictReportJSON rewrites archive bytes to the fixed report fields under
572	// their original spelling; see fixedShape for the recognition convention
573	// shared with the submission side.
574	func strictReportJSON(data []byte) ([]byte, error) {
575		return strictFixedJSON(data, reportShape)
576	}
577	
578	// loadStoredReport parses archive bytes for id and fully validates them.
579	func loadStoredReport(data []byte, id string) (Report, error) {
580		// Read-side counterpart of the submission check: json.Unmarshal silently
581		// keeps the last value for a repeated member, so an archive that writes a
582		// rule status as 发现缺陷 and then 通过 would decode to whichever came
583		// last. The recomputed id and the rule/finding correspondence all operate
584		// on that last-wins value and could therefore pass, accepting an archive
585		// with two conflicting conclusions. Any repeated member in any object
586		// makes the archive corrupt, regardless of the last value.
587		if dup := findDuplicateJSONMember(data); dup != nil {
588			return Report{}, duplicateArchiveError(id, data, dup)
589		}
590		strict, err := strictReportJSON(data)
591		if err != nil {
592			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
593		}
594		var r Report
595		if err := json.Unmarshal(strict, &r); err != nil {
596			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
597		}
598		if r.ReportID != id {
599			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
600		}
601		if err := validStoredReport(r); err != nil {
602			return Report{}, err
603		}
604		return r, nil
605	}
606	
607	// saveReportHook, when set, is invoked after the archive existence check and
608	// before the atomic publish. It lets tests simulate another process racing to
609	// claim the same report id.
610	var saveReportHook func(finalPath string)
611	
612	// SaveReport persists a report under the store directory. The store is safe
613	// for concurrent writers: identical reports share one file and all
614	// submissions succeed, different reports never overwrite each other, and
615	// readers only ever observe complete files. A submission is fully validated
616	// before any store operation, so an invalid report creates no store and no
617	// files. A pre-existing file with the same id must be a valid archive of the
618	// same report; a corrupted archive makes the submission fail while keeping the
619	// original file, even when the corruption appears only during the save. The
620	// first successfully archived bytes are never replaced by later submissions.
621	func SaveReport(dir string, r Report) error {
622		if err := validSubmittedReport(r); err != nil {
623			return err
624		}
625		if err := os.MkdirAll(dir, 0o755); err != nil {
626			return err
627		}
628		finalPath := filepath.Join(dir, r.ReportID+".json")
629		if existing, err := os.ReadFile(finalPath); err == nil {
630			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
631				return err
632			}
633			return nil
634		} else if !os.IsNotExist(err) {
635			return err
636		}
637		data, err := json.Marshal(r)
638		if err != nil {
639			return err
640		}
641		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
642		if err != nil {
643			return err
644		}
645		tmpPath := tmp.Name()
646		cleanup := func() { os.Remove(tmpPath) }
647		if _, err := tmp.Write(data); err != nil {
648			tmp.Close()
649			cleanup()
650			return err
651		}
652		if err := tmp.Sync(); err != nil {
653			tmp.Close()
654			cleanup()
655			return err
656		}
657		if err := tmp.Close(); err != nil {
658			cleanup()
659			return err
660		}
661		if saveReportHook != nil {
662			saveReportHook(finalPath)
663		}
664		if err := os.Link(tmpPath, finalPath); err != nil {
665			cleanup()
666			if os.IsExist(err) {
667				existing, readErr := os.ReadFile(finalPath)
668				if readErr != nil {
669					return readErr
670				}
671				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
672					return err
673				}
674				return nil
675			}
676			return err
677		}
678		cleanup()
679		return nil
680	}
681	
682	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
683	// hex characters; missing, corrupted or tampered archives produce a clear
684	// error. The store is only read, never created or modified.
685	func LoadReport(dir, id string) (Report, error) {
686		if !validReportID(id) {
687			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
688		}
689		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
690		if err != nil {
691			if os.IsNotExist(err) {
692				return Report{}, errNotFound("report " + id + " not found")
693			}
694			return Report{}, err
695		}
696		return loadStoredReport(data, id)
697	}
698	
699	type errNotFound string
700	
701	func (e errNotFound) Error() string { return string(e) }
702	
703	type errCorrupt string
704	
705	func (e errCorrupt) Error() string { return string(e) }
